import receiverEvents from "../const/receiverEvents";
import receiverState from "../const/receiverState";

class BitmovinReceiverPlayer {
  constructor() {
    this.bitmovinPlayer = null;
    this.mediaManager = null;
    this.castReceiverManager = null;
    this.state = receiverState.IDLE;
  }

  initialize() {
    const container = document.getElementById("player-container");

    // Real Bitmovin Player instance, running here on the receiver device —
    // not CAF's built-in Shaka player.
    this.bitmovinPlayer = new bitmovin.player.Player(container, {
      key: process.env.BITMOVIN_LICENSE_KEY,
      ui: false,
      logging: { level: "log" },
    });

    this._bindBitmovinEvents();
    this._initCastReceiver();
  }

  // v2 Cast Receiver API: CastReceiverManager + MediaManager. This is the
  // manual bridge Bitmovin's own historical receiver builds — you own the
  // whole message lifecycle here, unlike CAF v3's managed playerManager.
  _initCastReceiver() {
    this.castReceiverManager = cast.receiver.CastReceiverManager.getInstance();

    this.castReceiverManager.onReady(() => {
      this._dispatchToSender(receiverEvents.READY, {});
    });

    this.castReceiverManager.onSenderConnected((event) => {
      console.log("Sender connected:", event.data);
    });

    this.castReceiverManager.onSenderDisconnected((event) => {
      // Standard v2 pattern: stop and unload if the last sender leaves.
      if (this.castReceiverManager.getSenders().length === 0) {
        this.bitmovinPlayer.unload();
      }
    });

    this.mediaManager = new cast.receiver.MediaManager(this.castReceiverManager);

    // Override the default handlers to drive Bitmovin Player instead of
    // MPL's built-in playback.
    this.mediaManager.onLoad = this._onLoad.bind(this);
    this.mediaManager.onPlay = this._onPlay.bind(this);
    this.mediaManager.onPause = this._onPause.bind(this);
    this.mediaManager.onStop = this._onStop.bind(this);
    this.mediaManager.onSeek = this._onSeek.bind(this);
    this.mediaManager.onGetStatus = this._onGetStatus.bind(this);

    this.castReceiverManager.start();
  }

  _onLoad(event) {
    const media = event.data.media;
    const customData = event.data.customData || {};

    this._setState(receiverState.LOADING);

    const sourceConfig = this._buildSourceConfig(media, customData);

    this.bitmovinPlayer
      .load(sourceConfig)
      .then(() => {
        if (event.data.autoplay !== false) {
          this.bitmovinPlayer.play();
        }
        this.mediaManager.setMediaInformation(media);
        this.mediaManager.broadcastStatus(true);
      })
      .catch((error) => {
        this._dispatchToSender(receiverEvents.ERROR, { error: String(error) });
      });
  }

  // Translates the Cast LOAD request + your customReceiverConfig-carried
  // drmConfig (see src/solutions/bitmovin/tools/castConfig.js) into a real
  // Bitmovin Player source config — same shape your local bitmovin/player.js
  // adapter already builds for non-cast playback.
  _buildSourceConfig(media, customData) {
    const source = { title: media.metadata?.title };

    if (media.contentType === "application/dash+xml") {
      source.dash = media.contentId;
    } else if (media.contentType === "application/x-mpegURL") {
      source.hls = media.contentId;
    } else {
      source.progressive = media.contentId;
    }

    if (customData.drmConfig) {
      const drmConfig = JSON.parse(customData.drmConfig);
      source.drm = {};

      if (drmConfig.widevine) {
        source.drm.widevine = {
          LA_URL: drmConfig.widevine.laURL,
          headers: drmConfig.widevine.requestHeaderKey,
        };
      }
      // playready / fairplay follow the same shape as your existing
      // local DRM config translation — mirror configureDRM() here.
    }

    return source;
  }

  _onPlay() {
    this.bitmovinPlayer.play();
  }

  _onPause() {
    this.bitmovinPlayer.pause();
  }

  _onStop() {
    this.bitmovinPlayer.unload();
    this._setState(receiverState.IDLE);
  }

  _onSeek(event) {
    const targetTime = event.data.currentTime;
    if (typeof targetTime === "number") {
      this.bitmovinPlayer.seek(targetTime);
    }
  }

  _onGetStatus(event) {
    this.mediaManager.broadcastStatus(true);
  }

  _bindBitmovinEvents() {
    const bp = this.bitmovinPlayer;

    bp.on(bitmovin.player.PlayerEvent.Play, () => {
      this._setState(receiverState.PLAYING);
      this._dispatchToSender(receiverEvents.PLAYING, {});
    });

    bp.on(bitmovin.player.PlayerEvent.Paused, () => {
      this._setState(receiverState.PAUSED);
      this._dispatchToSender(receiverEvents.PAUSED, {});
    });

    bp.on(bitmovin.player.PlayerEvent.StallStarted, () => {
      this._setState(receiverState.BUFFERING);
      this._dispatchToSender(receiverEvents.BUFFERING, {});
    });

    bp.on(bitmovin.player.PlayerEvent.PlaybackFinished, () => {
      this._setState(receiverState.ENDED);
      this._dispatchToSender(receiverEvents.ENDED, {});
    });

    bp.on(bitmovin.player.PlayerEvent.Error, (error) => {
      this._dispatchToSender(receiverEvents.ERROR, { detail: error });
    });
  }

  _setState(state) {
    this.state = state;
  }

  _dispatchToSender(eventName, detail) {
    if (this.castReceiverManager) {
      this.castReceiverManager.sendCustomMessage(
        "urn:x-cast:com.bitmovin.player.receiver",
        undefined,
        { type: eventName, detail },
      );
    }
  }
}

export default BitmovinReceiverPlayer;